def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen, frames = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            S = set(cells)
            if r1-r0 >= 2 and c1-c0 >= 2 and all((r0,x) in S and (r1,x) in S for x in range(c0,c1+1)) and all((y,c0) in S and (y,c1) in S for y in range(r0,r1+1)):
                frames.append((color,r0,r1,c0,c1))
    for color, r0, r1, c0, c1 in frames:
        pat = [[grid[y][x] == color for x in range(c0+1,c1)] for y in range(r0+1,r1)]
        # Populate only completely empty frames with matching inner dimensions,
        # taking the other design and rotating it clockwise.
        for tc,tr0,tr1,tc0,tc1 in frames:
            if (tr0,tr1,tc0,tc1) == (r0,r1,c0,c1):
                continue
            target = [[grid[y][x] == tc for x in range(tc0+1,tc1)] for y in range(tr0+1,tr1)]
            if any(map(any,target)):
                continue
            rh, cw = len(pat), len(pat[0])
            rot = [[pat[rh-1-y][x] for y in range(rh)] for x in range(cw)]
            if len(rot) != tr1-tr0-1 or len(rot[0]) != tc1-tc0-1:
                continue
            for y,row in enumerate(rot):
                for x,v in enumerate(row):
                    out[tr0+1+y][tc0+1+x] = tc if v else 0
    return out
