def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            cellset = set(cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            is_frame = (
                all((r0, x) in cellset and (r1, x) in cellset for x in range(c0, c1 + 1)) and
                all((y, c0) in cellset and (y, c1) in cellset for y in range(r0, r1 + 1))
            )
            if is_frame:
                pattern = [[grid[y][x] == color for x in range(c0 + 1, c1)]
                           for y in range(r0 + 1, r1)]
                frames.append((color, r0, r1, c0, c1, pattern,
                               any(any(row) for row in pattern)))

    source = next((f for f in frames if f[6]), None)
    if source is None:
        return out
    _, _, _, _, _, pattern, _ = source
    sh, sw = len(pattern), len(pattern[0])
    for color, r0, r1, c0, c1, _, populated in frames:
        if (r1 - r0 - 1, c1 - c0 - 1) == (sh, sw):
            if not populated:
                for dy in range(sh):
                    for dx in range(sw):
                        out[r0 + 1 + dy][c0 + 1 + dx] = color if pattern[dy][dx] else 0
        else:
            # Frames that cannot receive the stencil are removed.
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    if out[y][x] == color:
                        out[y][x] = 0
    return out
